"""Five authored ordering deductions; not time-padding or generated filler."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
def bi(a,b):return {'vi':a,'en':b}
rows=[
('reconstruct','Khôi phục tấm ảnh','Reconstruct the photograph','Xếp các sự kiện từ sớm đến muộn theo ngày trên lịch và ảnh.','Arrange events from earliest to latest using the calendar and photograph.', [('Lời kể: Lan rời đi tháng bảy','Claim: Lan left in July'),('An sinh nhật ngày 17 tháng tám','An’s birthday on 17 August'),('An trở về sau đám tang năm 2008','An returns after the funeral in 2008')],['calendar','photo','letter'], 'Lời kể cũ không thể đứng cùng tấm ảnh. An ghi ngày thật trước khi mang hồ sơ đến trường.','The inherited account cannot stand beside the photograph. An records the dates before taking the papers to school.'),
('school_chain','Quy trình sửa sổ','How the register changed','Xếp các dấu vết theo trình tự tạo bản ghi, sửa và ký.','Order the traces by recording, alteration and signature.', [('Giấy than ghi lý do thu hồi đất','Carbon paper records land acquisition'),('Dòng tự ý nghỉ đè lên bản gốc','Voluntary departure overwrites the original'),('Hạnh ký xác nhận ngày 20 tháng tám','Hạnh signs on 20 August')],['carbon','register','attendance'],'Việc sửa xảy ra giữa hai thời điểm có thể đối chiếu, không phải lỗi trí nhớ của Lan.','The alteration falls between checkable events; it is not Lan misremembering.'),
('rescue_order','Dựng lại chuyến đò','Rebuild the rescue','Xếp ba ghi nhận theo thứ tự trong ngày.','Arrange the three records within the day.', [('Bến đóng lúc 16:00','Wharf closes at 16:00'),('Lộc rời bến lúc 17:10','Lộc departs at 17:10'),('Trạm tiếp nhận lúc 17:35','Clinic arrival at 17:35')],['radio','ferry','receipt'],'Khoảng trống sau giờ đóng bến chứa một quyết định quay lại, không phải bằng chứng bỏ mặc.','The gap after closure contains a decision to return, not evidence of abandonment.'),
('responsibility','Tách người làm và người hưởng','Separate action and benefit','Xếp chuỗi dẫn tới bức vẽ bị dùng làm chứng cứ, theo thư của mẹ.','Order how the drawing became evidence, according to Mother’s letter.', [('Mẹ muốn giữ suất nhà cho An','Mother wants to keep An’s housing allocation'),('Mẹ bảo An vẽ ngôi nhà trống','Mother tells An to draw an empty house'),('Người lớn đính bức vẽ vào đơn','Adults attach the drawing to the petition')],['draft','petition','ledger'],'An thêm chú thích tuổi của mình vào hồ sơ. Nhận trách nhiệm hôm nay không cần nhận một tội lỗi của người lớn khi mới chín tuổi.','An annotates her age in the file. Responsibility today does not mean taking on an adult’s culpability at nine.'),
('publication_order','Quy trình công bố','Publication process','Xếp quy trình phù hợp với điều Lan và Sơn yêu cầu.','Order the process that respects Lan’s and Sơn’s requirements.', [('Đối chiếu bản sao với chứng cứ gốc','Check copies against original evidence'),('Che thông tin riêng, gửi Lan duyệt lời trích','Redact private details; let Lan approve quotations'),('Gửi bản đã được duyệt tới biên tập viên','Submit the approved account to the editor')],['lan','editor','nhi'],'Bản thảo đã sẵn sàng. Việc có chờ người trong cuộc đồng ý hay không vẫn là quyết định của An.','The draft is ready. Whether to wait for the subject’s approval remains An’s choice.')]
s=json.loads((ROOT/'data/story.json').read_text())
for chapter,row in zip(s['chapters'],rows):
 id,vi,en,qv,qe,options,requires,rv,re=row
 chapter['puzzles']=[p for p in chapter['puzzles'] if p['id']!=id]
 chapter['puzzles'].append(dict(id=id,title=bi(vi,en),prompt=bi(qv,qe),options=[bi(*options[i]) for i in [2,0,1]],answer='120',requires=requires,hints=[bi('Bắt đầu từ nguyên nhân hoặc mốc sớm nhất.','Begin with the cause or earliest event.'),bi('Trình tự đúng: thẻ thứ hai, thẻ thứ ba, thẻ thứ nhất.','Correct order: second card, third card, first card.')],reveal=bi(rv,re),kind='sequence'))
(ROOT/'data/story.json').write_text(json.dumps(s,ensure_ascii=False,indent=2),encoding='utf8')
